    /**
     * 下载并转换
     */
    public static <T> List<T> downloadAndParse(String url, String compressionAlgorithm, Class<T> tClass, Map<String, String> columnMap) throws IOException {
        JSONArray jsonArray = download(url, compressionAlgorithm, columnMap);
        // 转换bean
        return JSONUtil.toList(jsonArray, tClass);
    }

    /**
     * 解析csv内容
     */
    public static CSVReader parseCSV(String csvContent) {
        CSVParser parser = new CSVParserBuilder()
                .withSeparator('\t')
                .withIgnoreQuotations(true)
                .build();
        return new CSVReaderBuilder(new StringReader(csvContent))
                .withCSVParser(parser)
                .build();
    }

    /**
     * 转换成指定class对象
     */
    public static <T> List<T> toBean(CSVReader reader, Class<T> clazz) {
        // 创建CsvToBean对象并指定映射到的类
        CsvToBean<T> csvToBean = new CsvToBeanBuilder<T>(reader)
                .withType(clazz)
                .withIgnoreLeadingWhiteSpace(true)
                .build();
        // 通过CsvToBean的parse方法解析CSV并将数据映射到对象列表
        return csvToBean.parse();
    }

